The api_path needs an inner quote:

```r
> swagger::swagger_spec
function (api_path = "http://petstore.swagger.io/v2/swagger.json", 
    version = "3") 
{
    index_file <- swagger_index(version = version)
    index_txt <- paste0(readLines(index_file), collapse = "\n")
    if (version == "3") {
        index_txt <- sub("\"(http|https)://petstore.swagger.io/v2/swagger.json\"", 
            api_path, index_txt)
    }
    else {
        stop("swagger_spec not implemented for version: ", version)
    }
    index_txt
}
```
